pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant HUGE = 2**128 - 1;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(
        uint256 unlockTime1,
        uint256 unlockTime2,
        uint256 dep1,
        uint256 dep2
    ) public {
        // Keep deposits within reachable balance, prevent overflow
        uint256 bal = address(this).balance;
        bound(dep1, 0, bal / 2);
        bound(dep2, 0, bal / 2);
        // Unlock times: use reasonable timestamps, but allow anything in [0..HUGE]
        bound(unlockTime1, 0, HUGE);
        bound(unlockTime2, 0, HUGE);

        // Use a single EOA caller to perform all actions
        address actor = vm.addr(1);
        // Deal enough Ether to cover deposits
        vm.deal(actor, dep1 + dep2);

        // Record total Ether sent by `actor` via Put/fallback
        uint256 totalDeposited = 0;

        // First Put
        vm.prank(actor);
        c.Put{value: dep1}(unlockTime1);
        totalDeposited += dep1;

        // Read balance and unlockTime after first Put
        (uint256 unlockTimeA, uint256 balA) = c.Acc(actor);

        // Advance time past both unlock times to allow Collect
        vm.warp(max(unlockTime1, unlockTime2) + 1);

        // Record total successfully collected by `actor`
        uint256 totalCollected = 0;

        // Collect all from the first deposit
        if (balA >= c.MinSum() && balA > 0) {
            vm.prank(actor);
            try c.Collect(balA) {
                totalCollected += balA;
            } catch {}
        }

        // Second Put
        vm.prank(actor);
        c.Put{value: dep2}(unlockTime2);
        totalDeposited += dep2;

        // Read balance after second Put
        ( , uint256 balB) = c.Acc(actor);

        // Collect all from the second deposit
        if (balB >= c.MinSum() && balB > 0) {
            vm.prank(actor);
            try c.Collect(balB) {
                totalCollected += balB;
            } catch {}
        }

        // Final balance check
        ( , uint256 finalBal) = c.Acc(actor);

        // Universal invariant: actor's final balance + total collected == total deposited
        // For the reference, this holds; for the mutant (balance reset to 0 after each Put),
        // totalCollected is zero (balance never reaches MinSum), so the LHS is smaller,
        // breaking the equality.
        assertTrue(finalBal + totalCollected == totalDeposited);
    }

    function max(uint256 a, uint256 b) private pure returns (uint256) {
        return a > b ? a : b;
    }
}

