import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 collectAmt, uint48 unlockDelay, address actor) public {
        // Keep amounts in admissible domain: non-zero, and collectAmt <= balance
        vm.assume(actor != address(0));
        amount = bound(amount, 1, address(this).balance / 2);
        collectAmt = bound(collectAmt, 1, amount);
        // unlockDelay in (0, type(uint48).max] to keep unlockTime > block.timestamp
        vm.assume(unlockDelay > 0);

        // Give actor Ether
        vm.deal(actor, amount);

        // Put funds into contract
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + unlockDelay);

        // Warp past unlock time
        vm.warp(block.timestamp + unlockDelay + 1);

        // Attempt to Collect
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Property: if actor's balance is less than MinSum, Collect must fail
        uint256 accBal = c.Acc(actor).balance;
        if (accBal < c.MinSum()) {
            assertTrue(!ok);
        } else {
            // If balance >= MinSum, Collect may succeed or fail (no constraint)
            assertTrue(true);
        }
    }
